using System; using System.Net.Http; using System.Threading.Tasks; using AIHelper.Services.StockData; using AIHelper.Models; using AIHelper.Infrastructure.Services.StockData; class Program { static async Task Main() { var client = new HttpClient(); var cache = new LocalStockCacheProvider(); var eastMoney = new EastMoneyStockDataProvider(client, cache); var quote = await eastMoney.GetDataAsync(new StockDataRequest("/api/quote") { ["code"] = "000001,600000" }); Console.WriteLine("QUOTE: " + quote.Json); var kline = await eastMoney.GetDataAsync(new StockDataRequest("/api/kline-all") { ["code"] = "000001", ["limit"] = "5" }); Console.WriteLine("KLINE: " + kline.Json); } }
